export function unwrapUserChosen(chosen) {
  if (chosen === undefined || chosen === null) return '';
  if (typeof chosen === 'object' && !Array.isArray(chosen)) {
    if (chosen.chosen !== undefined) {
      return unwrapUserChosen(chosen.chosen);
    }
  }
  return chosen;
}

export function parseNumericValue(raw) {
  if (raw === undefined || raw === null) return null;
  let t = String(raw).trim().toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[{}$\\]/g, '')
    .replace(/×/g, '*')
    .replace(/,/g, '.');
  if (!t) return null;
  t = t.replace(/\bpi\b|π/g, String(Math.PI));
  if (t.includes('/')) {
    const parts = t.split('/');
    if (parts.length === 2) {
      const num = parseNumericValue(parts[0]);
      const den = parseNumericValue(parts[1]);
      if (num !== null && den !== null && den !== 0) return num / den;
    }
  }
  if (t.includes('*')) {
    const parts = t.split('*');
    if (parts.length === 2) {
      const a = parseNumericValue(parts[0]);
      const b = parseNumericValue(parts[1]);
      if (a !== null && b !== null) return a * b;
    }
  }
  const n = parseFloat(t);
  return isNaN(n) ? null : n;
}

export function evaluateQuestion(q, rawChosen) {
  const chosen = unwrapUserChosen(rawChosen);
  if (!q || chosen === undefined || chosen === null || chosen === '') return false;
  const qType = q.tipe || '';
  const kunci = q.kunci;
  if (kunci === undefined || kunci === null) return false;

  const isNumeric = qType === 'Isian Singkat Numerik' || qType === 'Numeric Entry';
  const isTF = !isNumeric && (qType === 'Pilihan Benar / Salah' || qType === 'True / False' || (kunci && /^[BSTF]\s*-\s*[BSTF]/i.test(String(kunci))));
  const isMulti = !isNumeric && !isTF && (qType === 'Pilihan Ganda Kompleks' || qType === 'Multiple Response' || (kunci && String(kunci).includes(',')));

  if (isTF) {
    const normalizeTF = (val) => {
      if (val === undefined || val === null) return '';
      if (typeof val === 'boolean') return val ? 'B' : 'S';
      const s = String(val).trim().toUpperCase();
      if (!s) return '';
      const c = s[0];
      if (c === 'T') return 'B';
      if (c === 'F') return 'S';
      return c;
    };
    const correctParts = String(kunci).split('-').map(normalizeTF).filter(Boolean);
    if (correctParts.length === 0) return false;
    let userParts = {};
    if (Array.isArray(chosen)) {
      chosen.forEach((val, idx) => { userParts[idx] = val; });
    } else if (typeof chosen === 'object' && chosen !== null) {
      userParts = chosen;
    } else if (typeof chosen === 'string') {
      const sep = chosen.includes('-') ? '-' : (chosen.includes(',') ? ',' : (chosen.includes('/') ? '/' : ''));
      if (sep) {
        chosen.split(sep).forEach((val, idx) => { userParts[idx] = val.trim(); });
      } else {
        return false;
      }
    } else {
      return false;
    }
    const isOneIndexed = (userParts[0] === undefined && userParts['0'] === undefined && (userParts[1] !== undefined || userParts['1'] !== undefined));
    for (let i = 0; i < correctParts.length; i++) {
      const key = isOneIndexed ? i + 1 : i;
      let uVal = userParts[key] !== undefined ? userParts[key] : userParts[String(key)];
      if (uVal === undefined || uVal === null || uVal === '') return false;
      const uNorm = normalizeTF(uVal);
      if (uNorm !== correctParts[i]) return false;
    }
    return true;
  }

  if (isMulti) {
    const correctSet = String(kunci).split(',').map(s => s.trim().toUpperCase()).filter(Boolean).sort();
    let userArr = [];
    if (Array.isArray(chosen)) {
      userArr = chosen;
    } else if (typeof chosen === 'string') {
      userArr = chosen.split(',');
    } else if (typeof chosen === 'object' && chosen !== null) {
      userArr = Object.values(chosen);
    }
    const userSet = userArr.map(s => String(s).trim().toUpperCase()).filter(Boolean).sort();
    if (userSet.length === 0 || correctSet.length === 0) return false;
    if (userSet.length !== correctSet.length) return false;
    return correctSet.every((val, idx) => val === userSet[idx]);
  }

  if (isNumeric) {
    const strChosen = String(chosen).trim().toLowerCase().replace(/\s+/g, '');
    const strKunci = String(kunci).trim().toLowerCase().replace(/\s+/g, '');
    if (strChosen === strKunci) return true;
    const numChosen = parseNumericValue(strChosen);
    const numKunci = parseNumericValue(strKunci);
    if (numChosen !== null && numKunci !== null) {
      return Math.abs(numChosen - numKunci) <= Math.max(0.005, Math.abs(numKunci) * 0.01);
    }
    return false;
  }

  // Single Choice (Pilihan Ganda Tunggal)
  const normChosen = String(chosen).trim().toUpperCase()[0];
  const normKunci = String(kunci).trim().toUpperCase()[0];
  return normChosen === normKunci;
}

export function calculateOfficialGrade(tingkat, mapel, kodePertemuan, answers) {
  if (!answers || (Array.isArray(answers) && answers.length === 0)) {
    return null;
  }

  const cleanTingkat = String(tingkat || '').replace(/[^0-9]/g, '');
  const cleanMapel = String(mapel || 'wajib').trim().toLowerCase();
  const cleanKode = String(kodePertemuan || '').trim().toLowerCase();

  const keyFull = `${cleanTingkat}_${cleanMapel}_${cleanKode}`;
  const keyShort = `${cleanMapel}_${cleanKode}`;

  const questions = ANSWER_KEYS[keyFull] || ANSWER_KEYS[keyShort] || null;
  if (!questions || !Array.isArray(questions) || questions.length === 0) {
    return null; // Package key not found in server keys
  }

  // Build answer lookup map
  const answerMap = {};
  if (Array.isArray(answers)) {
    answers.forEach((item, idx) => {
      if (item && item.q_idx !== undefined) {
        answerMap[Number(item.q_idx)] = unwrapUserChosen(item.chosen !== undefined ? item.chosen : item);
      } else if (item && item.chosen !== undefined) {
        answerMap[idx] = unwrapUserChosen(item.chosen);
      } else {
        answerMap[idx] = unwrapUserChosen(item);
      }
    });
  } else if (typeof answers === 'object' && answers !== null) {
    Object.keys(answers).forEach(k => {
      answerMap[Number(k)] = unwrapUserChosen(answers[k]);
    });
  }

  let jumlahBenar = 0;
  const totalSoal = questions.length;
  const evaluations = [];
  const details = [];

  for (let i = 0; i < totalSoal; i++) {
    const q = questions[i];
    const userChosen = answerMap[i];
    const isRight = evaluateQuestion(q, userChosen);
    if (isRight) {
      jumlahBenar++;
    }
    evaluations.push(Boolean(isRight));
    details.push({
      q_idx: i,
      is_right: Boolean(isRight),
      kunci: q.kunci || '',
      chosen: userChosen !== undefined ? userChosen : null
    });
  }

  const jumlahSalah = totalSoal - jumlahBenar;
  const skor = Math.round((jumlahBenar / totalSoal) * 100);

  return {
    skor: skor,
    jumlah_soal: totalSoal,
    jumlah_benar: jumlahBenar,
    jumlah_salah: jumlahSalah,
    evaluations: evaluations,
    details: details,
    server_verified: true
  };
}
